mapper.select:
/* AppLeave01Mapper.selectGroupAgg */
SELECT
      (
        SELECT SUM(G.GRANT_DAYS)
          FROM TB_USER_LEAVE_GRANT G
         WHERE G.CMPNY_CD = #{ param.cmpnyCd }
           AND G.USER_CD = #{ param.userCd }
           AND G.STATUS = 'ACTIVE'
           AND G.EXPIRE_YN = 'N'
           AND G.DEL_YN = 'N'
           AND NOT (G.GRANT_REASON LIKE '[가불]%' AND G.AVAIL_FROM_DATE  >  #{ param.todayYmd })

           AND G.GRANT_TYPE LIKE #{ param.grantTypePrefix }

      ) AS granted
    , (
        SELECT SUM(G.USED_DAYS)
          FROM TB_USER_LEAVE_GRANT G
         WHERE G.CMPNY_CD = #{ param.cmpnyCd }
           AND G.USER_CD = #{ param.userCd }
           AND G.STATUS = 'ACTIVE'
           AND G.EXPIRE_YN = 'N'
           AND G.DEL_YN = 'N'
           AND NOT (G.GRANT_REASON LIKE '[가불]%' AND G.AVAIL_FROM_DATE  >  #{ param.todayYmd })

           AND G.GRANT_TYPE LIKE #{ param.grantTypePrefix }

      ) AS usedTotal
    , (
        SELECT SUM(LU.LEAVE_DAYS)
          FROM TB_USER_LEAVE_USE LU
          JOIN TB_USER_LEAVE_GRANT G
            ON G.CMPNY_CD = LU.CMPNY_CD
           AND G.GRANT_ID = LU.GRANT_ID
           AND G.STATUS = 'ACTIVE'
           AND G.EXPIRE_YN = 'N'
           AND G.DEL_YN = 'N'
           AND NOT (G.GRANT_REASON LIKE '[가불]%' AND G.AVAIL_FROM_DATE  >  #{ param.todayYmd })

           AND G.GRANT_TYPE LIKE #{ param.grantTypePrefix }

         WHERE LU.CMPNY_CD = #{ param.cmpnyCd }
           AND LU.USER_CD = #{ param.userCd }
           AND LU.LEAVE_STATUS = 'CONFIRMED'
           AND LU.DEL_YN = 'N'
           AND LU.START_DATE  >  #{ param.todayYmd }
      ) AS planned
FROM DUAL

/* AppLeave01Mapper.selectBorrowedDaysTotal */
SELECT IFNULL(SUM(G.USED_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD       = #{cmpnyCd}
   AND G.USER_CD        = #{userCd}
   AND G.GRANT_REASON   LIKE '[가불]%'
   AND G.STATUS        != 'CANCELED'
   AND G.DEL_YN         = 'N'
   AND G.AVAIL_FROM_DATE  >  #{today}

/* AppLeave01Mapper.selectHourlyUsedMinutes */
SELECT IFNULL(SUM(U.LEAVE_MINUTES), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD      = #{cmpnyCd}
   AND U.USER_CD       = #{userCd}
   AND U.USE_UNIT_TYPE IN ('02', '03', '04')
   AND U.LEAVE_STATUS  = 'CONFIRMED'
   AND U.DEL_YN        = 'N'

/* AppLeave01Mapper.selectLeaveUsesByRange */ SELECT U.LEAVE_ID AS leaveId , U.START_DATE AS startDate , U.END_DATE AS endDate , U.START_TIME AS startTime , U.END_TIME AS endTime , U.USE_UNIT_TYPE AS useUnitType
, CASE WHEN U.REQ_ID IS NULL THEN U.LEAVE_DAYS ELSE ( SELECT SUM(X.LEAVE_DAYS) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = U.CMPNY_CD AND X.REQ_ID = U.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) END AS leaveDays , U.LEAVE_MINUTES AS leaveMinutes , LT.LEAVE_NM AS leaveNm FROM TB_USER_LEAVE_USE U LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = U.CMPNY_CD AND LT.LEAVE_CD = U.LEAVE_CD WHERE U.CMPNY_CD = #{cmpnyCd} AND U.USER_CD = #{userCd} AND U.LEAVE_STATUS = 'CONFIRMED' AND U.DEL_YN = 'N' AND U.START_DATE BETWEEN #{fromYmd} AND #{toYmd}
AND ( U.REQ_ID IS NULL OR U.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = U.CMPNY_CD AND X.REQ_ID = U.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) ) ORDER BY U.START_DATE DESC, U.START_TIME DESC, U.LEAVE_ID DESC LIMIT 500
